<?php require_once __DIR__.'/../config.php';require_admin();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM applications WHERE id=?');$s->execute([$id]);$a=$s->fetch();if(!$a)exit('Not found.');$s=db()->prepare('SELECT * FROM application_events WHERE application_id=? ORDER BY created_at DESC');$s->execute([$id]);$events=$s->fetchAll();$msg=flash();?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($a['application_no'])?> · PartnerHub</title><link rel="stylesheet" href="../assets/style.css"></head><body class="admin"><header class="admin-top"><a class="logo" href="../index.php"><span class="logo-mark">P</span>PartnerHub</a><div><a href="index.php">← Applications</a><a href="logout.php">Sign out</a></div></header><main class="case"><div class="admin-heading"><div><span class="kicker"><?=e($a['application_no'])?></span><h1><?=e($a['company_name'])?></h1><p><?=e($a['contact_name'])?> · <?=e($a['email'])?></p></div><span class="pill pill-<?=e($a['status'])?>"><?=e(str_replace('_',' ',$a['status']))?></span></div><?php if($msg):?><div class="success-msg"><?=e($msg)?></div><?php endif;?><div class="columns"><section class="detail-card"><h3>Company profile</h3><dl><dt>Website</dt><dd><?=e($a['website']?:'Not provided')?></dd><dt>Country</dt><dd><?=e($a['country']?:'Not provided')?></dd><dt>Size</dt><dd><?=e($a['company_size'])?></dd><dt>Partner type</dt><dd><?=e($a['partner_type'])?></dd><dt>Regions</dt><dd><?=e($a['regions']?:'Not provided')?></dd></dl><hr><h3>Capabilities</h3><p><?=nl2br(e($a['services']))?></p><h3>Relevant experience</h3><p><?=nl2br(e($a['experience']?:'Not provided'))?></p><h3>Partnership goals</h3><p><?=nl2br(e($a['goals']))?></p></section><aside><form class="detail-card" method="post" action="update.php"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><h3>Review application</h3><label>Status<select name="status"><?php foreach(['pending','reviewing','more_info','approved','declined'] as $v):?><option value="<?=$v?>" <?=$a['status']===$v?'selected':''?>><?=ucwords(str_replace('_',' ',$v))?></option><?php endforeach;?></select></label><label>Reviewer note / applicant update<textarea name="admin_note" rows="7"><?=e($a['admin_note'])?></textarea></label><button class="btn primary full">Save decision →</button></form><div class="detail-card"><h3>Activity</h3><?php foreach($events as $e):?><div class="event"><b>•</b><p><?=e($e['event_text'])?><small><?=e($e['created_at'])?></small></p></div><?php endforeach;?></div></aside></div></main></body></html>